    # artist_list can be list of names or comma-separated string
    if isinstance(artist_list, str):
        names = [n.strip() for n in artist_list.split(',')]
    else:
        names = [n.strip() for n in artist_list]
    return set(names)

old_song_keys = set()
for title, artist_str in old_songs:
    artist_set = normalize_artists(artist_str)
    old_song_keys.add((title.strip().lower(), frozenset(artist_set)))

matching_song_ids = set()
for song_id, song in song_details.items():
    title = song['title'].strip().lower()
    artists = normalize_artists([a['name'] for a in song['artists']])
    if (title, frozenset(artists)) in old_song_keys:
        matching_song_ids.add(song_id)
        print(f"Match: {song['title']} by {[a['name'] for a in song['artists']]} (id={song_id})")

